// TopK streams r, tokenizes its contents into words, and returns the k most
// frequent words: counts in descending order, ties broken by the word in
// ascending byte order.
//
// A word is a maximal run of Unicode letters or digits, optionally containing
// apostrophes that sit between two letters (e.g. "don't"); a leading or
// trailing apostrophe does not belong to the word. Words are case-folded
// with strings.ToLower. Words whose lower-cased form appears in stop are
// ignored.
//
// The input is processed as a stream: it is not read into memory, so very
// large inputs and very long lines are fine. If there are fewer than k
// distinct words, all of them are returned; if k <= 0, an empty (non-nil)
// slice is returned. Any read error from r is returned.
func TopK(r io.Reader, k int, stop []string) ([]WordCount, error) {
	if k <= 0 {
		return []WordCount{}, nil
	}

	stopSet := make(map[string]struct{}, len(stop))
	for _, w := range stop {
		stopSet[strings.ToLower(w)] = struct{}{}
	}

	counts := make(map[string]int)
	var buf []rune
	inWord := false
	flush := func() {
		if !inWord {
			return
		}
		n := len(buf)
		if n > 0 && buf[n-1] == '\'' {
			n--
		}
		if n > 0 {
			w := strings.ToLower(string(buf[:n]))
			if _, isStop := stopSet[w]; !isStop {
				counts[w]++
			}
		}
		buf = buf[:0]
		inWord = false
	}
	process := func(r rune) {
		switch {
		case unicode.IsLetter(r):
			if inWord {
				buf = append(buf, r)
			} else {
				buf = append(buf[:0], r)
				inWord = true
			}
		case r == '\'':
			if inWord {
				if unicode.IsLetter(buf[len(buf)-1]) {
					buf = append(buf, r)
				} else {
					flush()
				}
			}
			// not in a word: leading apostrophe, ignore
		default:
			flush()
		}
	}

	br := bufio.NewReaderSize(r, 1<<20)
	for {
		r, _, err := br.ReadRune()
		if err != nil {
			if _, ok := br.UnreadRune(); ok {
				process(r) // last rune of a multi-byte char still valid
			}
			flush()
			if err != io.EOF {
				return nil, err
			}
