{"content":"package words

import (
	"errors"
	"fmt"
	"io"
	"reflect"
	"strings"
	"testing"
)

func check(t *testing.T, in string, k int, stop []string, want []WordCount) {
	t.Helper()
	got, err := TopK(strings.NewReader(in), k, stop)
	if err != nil {
		t.Fatalf("TopK(%q): %v", in, err)
	}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("TopK(%q, k=%d, stop=%v) = %v, want %v", in, k, stop, got, want)
	}
}

func TestBasicCounting(t *testing.T) {
	check(t, "the cat and the dog and the cat and the fish", 2, nil,
		[]WordCount{{"the", 5}, {"cat", 2}})
}

func TestCaseFolding(t *testing.T) {
	check(t, "Cat cat CAT", 1, nil, []WordCount{{"cat", 3}})
}

func TestStopWordsCaseInsensitive(t *testing.T) {
	check(t, "the The THE cat the dog", 5, []string{"THE"},
		[]WordCount{{"cat", 1}, {"dog", 1}})
	check(t, "the the the", 3, []string{"The"}, []WordCount{})
}

func TestApostrophes(t *testing.T) {
	check(t, "don't don't don't", 1, nil, []WordCount{{"don't", 3}})
	check(t, "o'clock o'Clock", 1, nil, []WordCount{{"o'clock", 2}})
	check(t, "rockin' rockin' rockin' x", 2, nil,
		[]WordCount{{"rockin'", 2}, {"x", 1}}) // trailing apostrophe kept as letter run ends at digit? no:
}

func TestTrailingAndLeadingApostrophes(t *testing.T) {
	// trailing apostrophe is not part of the word
	check(t, "don'ts it's", 10, nil, []WordCount{{"don", 1}, {"it", 1}})
	// leading apostrophe is not part of the word
	check(t, "'twas", 1, nil, []WordCount{{"twas", 1}})
	// apostrophe between a digit and a letter separates
	check(t, "a1'b", 10, nil, []WordCount{{"1", 1}, {"a", 1}, {"b", 1}})
	// digits are word characters, apostrophes only between letters
	check(t, "abc123def", 1, nil, []WordCount{{"abc123def", 1}})
}

func TestSeparators(t *testing.T) {
	check(t, "hello, world! \"quoted\" (paren) [bracket] tab\tnewline\nend", 10, nil,
		[]WordCount{{"end", 1}, {"bracket", 1}, {"hello", 1}, {"newline", 1}, {"paren", 1}, {"quoted", 1}, {"tab", 1}, {"world", 1}})
}

func TestUnicodeLetters(t *testing.T) {
	check(t, "Café café naïve café", 2, nil,
		[]WordCount{{"café", 2}, {"naïve", 1}})
}

func TestKGreaterThanDistinct(t *testing.T) {
	check(t, "a b c", 10, nil, []WordCount{{"a", 1}, {"b", 1}, {"c", 1}})
}

func TestKZeroAndNegative(t *testing.T) {
	got, err := TopK(strings.NewReader("a b c"), 0, nil)
	if err != nil {
		t.Fatal(err)
	}
	if got == nil || len(got) != 0 {
		t.Errorf("k=0: got %v (len %d), want empty non-nil slice", got, len(got))
	}
	got, err = TopK(strings.NewReader("a b c"), -3, nil)
	if err != nil {
		t.Fatal(err)
	}
	if got == nil || len(got) != 0 {
		t.Errorf("k<0: got %v (len %d), want empty non-nil slice", got, len(got))
	}
}

func TestEmptyInput(t *testing.T) {
	got, err := TopK(strings.NewReader(""), 5, nil)
	if err != nil {
		t.Fatal(err)
	}
	if got == nil || len(got) != 0 {
		t.Errorf("empty input: got %v, want empty non-nil slice", got)
	}
}

func TestReadError(t *testing.T) {
	errBoom := errors.New("boom")
	got, err := TopK(io.MultiReader(strings.NewReader("some long words here that"), errBoom), 5, nil)
	if !errors.Is(err, errBoom) {
		t.Fatalf("err = %v, want errBoom", err)
	}
	_ = got
}

func TestLongLine(t *testing.T) {
	// a single "line" of 50 MB of repeated words must work and be streamed
	var sb strings.Builder
	for sb.Len() < 50<<20 {
		sb.WriteString("don't ")
	}
	got, err := TopK(&sb, 1, nil)
	if err != nil {
		t.Fatal(err)
	}
	want := []WordCount{{"don't", sb.Len() / 6}}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("long line: got %v, want %v", got, want)
	}
}

// multiByteEOF feeds content in awkward chunk sizes and ends mid-rune-stream.
type chunkReader struct {
	data []byte
	pos  int
	chunk int
}

func (c *chunkReader) Read(p []byte) (int, error) {
	if c.pos >= len(c.data) {
		return 0, io.EOF
	}
	n := len(c.data) - c.pos
	if n > c.chunk {
		n = c.chunk
	}
	copy(p, c.data[c.pos:c.pos+n])
	c.pos += n
	return n, nil
}

func TestUTF8Chunks(t *testing.T) {
	in := "café café naïve café don't o'clock"
	for _, chunk := range []int{1, 2, 3, 4, 7} {
		got, err := TopK(&chunkReader{data: []byte(in), chunk: chunk}, 10, nil)
		if err != nil {
			t.Fatalf("chunk %d: %v", chunk, err)
		}
		want := []WordCount{{"café", 3}, {"don't", 1}, {"naïve", 1}, {"o'clock", 1}}
		if !reflect.DeepEqual(got, want) {
			t.Errorf("chunk %d: got %v, want %v", chunk, got, want)
		}
	}
}

